export default function createNode(config, ctx) {
  const { assets, scenePosition, sceneRotation, sceneScale } = config;

  // Load texture
  const map = ctx.textureLoader.load(assets.imageUrl);

  // Unlit material
  const material = new MeshBasicNodeMaterial({
    map: map,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Geometry: 1x1 aspect (will be scaled) – source rect 512x320 => aspect 1.6
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(1, 1 / aspect);

  const mesh = new Mesh(geometry, material);
  mesh.position.set(scenePosition[0], scenePosition[1], scenePosition[2]);
  mesh.rotation.set(sceneRotation[0], sceneRotation[1], sceneRotation[2]);
  mesh.scale.set(sceneScale[0], sceneScale[1], sceneScale[2]);

  // No handlers
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    map?.dispose?.();
  };

  // Apply cinematic primitives (none)
  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    ctx.primitives[p.name](mesh, p.params);
  }

  return mesh;
}
